using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using Emberfall;
namespace UnityEngine{
 public enum RuntimeInitializeLoadType{SubsystemRegistration}public class RuntimeInitializeOnLoadMethodAttribute:Attribute{public RuntimeInitializeOnLoadMethodAttribute(RuntimeInitializeLoadType x){}}
 public class Object{public string name;public bool destroyed;public static GameObject Instantiate(GameObject x,Transform p,bool w)=>x.Clone(p);public static void Destroy(Object x){if(x==null)return;x.destroyed=true;if(x is GameObject g){g.SetActive(false);foreach(var c in g.Components.ToArray())c.GetType().GetMethod("OnDestroy",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(c,null);foreach(var t in g.transform.Children.ToArray())Destroy(t.gameObject);}}}
 public class Component:Object{public GameObject gameObject;public Transform transform=>gameObject.transform;public T[] GetComponentsInChildren<T>(bool inactive)where T:Component=>gameObject.GetComponentsInChildren<T>(inactive);}
 public class MonoBehaviour:Component{}
 public class Transform:Component{public Vector3 localPosition,localScale=Vector3.one;public Quaternion localRotation;public Transform parent;public List<Transform> Children=new List<Transform>();public Vector3 position=>parent==null?localPosition:parent.position+localPosition;public void SetParent(Transform p){parent=p;p?.Children.Add(this);}public bool IsChildOf(Transform p)=>this==p||(parent!=null&&parent.IsChildOf(p));public Vector3 TransformPoint(Vector3 p)=>position+p;}
 public class GameObject:Object{public static readonly List<GameObject> All=new List<GameObject>();public readonly List<Component> Components=new List<Component>();public Transform transform;public bool activeSelf=true;public bool activeInHierarchy=>activeSelf&&(transform.parent==null||transform.parent.gameObject.activeInHierarchy);public GameObject(string n=""){All.Add(this);name=n;transform=AddComponent<Transform>();transform.name=n;}public void SetActive(bool a){activeSelf=a;}public T AddComponent<T>()where T:Component,new(){var c=new T{gameObject=this};Components.Add(c);return c;}public T[] GetComponentsInChildren<T>(bool inactive)where T:Component=>Components.OfType<T>().Concat(transform.Children.SelectMany(t=>t.gameObject.GetComponentsInChildren<T>(inactive))).ToArray();public GameObject Clone(Transform p){var g=new GameObject(name);g.transform.SetParent(p);g.transform.localPosition=transform.localPosition;g.transform.localScale=transform.localScale;g.transform.localRotation=transform.localRotation;g.activeSelf=activeSelf;foreach(var c in Components){if(c is Renderer r){var v=g.AddComponent<Renderer>();v.enabled=r.enabled;v.sharedMaterial=r.sharedMaterial;}if(c is MeshFilter m)g.AddComponent<MeshFilter>().sharedMesh=m.sharedMesh;if(c is Animator a){var v=g.AddComponent<Animator>();v.enabled=a.enabled;v.applyRootMotion=a.applyRootMotion;}if(c is Animation a2){var v=g.AddComponent<Animation>();v.enabled=a2.enabled;v.playAutomatically=a2.playAutomatically;}}foreach(var t in transform.Children)t.gameObject.Clone(g.transform);return g;}}
 public class Renderer:Component{public bool enabled=true;public Material sharedMaterial;}public class Material:Object{}public class Mesh:Object{}public class MeshFilter:Component{public Mesh sharedMesh;}public class Animator:Component{public bool enabled=true,applyRootMotion=true;}public class Animation:Component{public bool enabled=true,playAutomatically=true;}
 public class AnimationClip:Object{public float length=2;public static AnimationClip Last;public static float At;public static int Samples;public void SampleAnimation(GameObject g,float t){Last=this;At=t;Samples++;var tip=g.GetComponentsInChildren<Transform>(true).FirstOrDefault(x=>x.name=="Anchor_Tip");if(tip!=null)tip.localPosition=new Vector3(t,1,0);}}
 public static class Resources{public static Dictionary<string,Object> Items=new Dictionary<string,Object>();public static AnimationClip[] Clips=new AnimationClip[0];public static int Loads;public static T Load<T>(string n)where T:Object{Loads++;return Items.TryGetValue(n,out var v)?v as T:null;}public static T[] LoadAll<T>(string n)where T:Object=>Clips.OfType<T>().ToArray();}
 public struct Vector3{public float x,y,z;public Vector3(float a,float b,float c){x=a;y=b;z=c;}public static Vector3 zero=>new Vector3();public static Vector3 one=>new Vector3(1,1,1);public static Vector3 operator +(Vector3 a,Vector3 b)=>new Vector3(a.x+b.x,a.y+b.y,a.z+b.z);}
 public struct Quaternion{public static Quaternion identity=>new Quaternion();}public static class Time{public static float time,deltaTime;public static int frameCount;}public static class Mathf{public static float Abs(float x)=>Math.Abs(x);public static float Min(float a,float b)=>Math.Min(a,b);}
}
